import{forceFigure}from './frc1-figures.js?v=20261023-physicscomplete01';
const entries=[['work','Force through a displacement',['Begin the along-force displacement.','The force transfers energy as the object moves.','More distance means more work at fixed force.','The worked example resets on replay.']],['elasticity','Stretch a linear elastic spring',['Start from the original length.','Opposing forces stretch the spring.','Extension increases within the linear region.','The loaded spring stores elastic potential energy.']],['moments','Compare turning effects',['Locate the fixed pivot.','Apply a force with a perpendicular lever arm.','An unequal moment produces a turning tendency.','Balance requires equal opposing moment totals.']],['atmosphere','Air molecules and atmospheric pressure',['Air molecules move randomly.','Collisions transfer momentum to surfaces.','At higher altitude fewer molecules lie above.','Pressure is lower where the overlying column is smaller.']],['motion','A constant-speed journey',['Start at the origin.','Travel equal distances in equal times.','Distance accumulates along the route.','Final distance equals speed times time.']],['acceleration','Accelerate uniformly from rest',['Begin at rest.','Velocity increases at a constant rate.','Distance grows faster as velocity rises.','Reset the example rather than reversing its history.']],['velocitygraph','Trace a velocity–time segment',['Read initial velocity.','Follow the straight segment.','Velocity changes uniformly with time.','Gradient represents acceleration.']],['terminal','Compare falling force accounts',['Weight acts downward.','Increasing speed usually increases drag.','The downward resultant shrinks.','At terminal velocity drag balances weight.']],['firstlaw','Coast with zero resultant',['An ideal trolley is already moving.','No resultant changes its velocity.','It covers equal distances in equal times.','Constant velocity continues without a driving force.']],['secondlaw','Resultant force changes velocity',['Start with a selected moving-system mass.','A constant resultant acts.','Acceleration equals force divided by mass.','Velocity increases in the force direction.']],['stopping','Travel during the reaction interval',['A hazard is noticed.','The vehicle continues before brakes act.','Thinking distance accumulates at the selected speed.','Braking begins after the reaction interval.']],['braking','An ideal constant-force stop',['Initial motion has kinetic energy.','An opposing force does work.','Velocity falls as internal energy increases.','The vehicle reaches rest in this ideal example.']],['momentum','Momentum has a direction',['Choose mass and a signed velocity.','The object moves in its velocity direction.','Momentum points in the same direction.','The product mv stays constant in this ideal coast.']],['collisions','A sticking trolley collision',['A moving trolley approaches a stationary target.','The trolleys interact.','They stick and share a common velocity.','The signed total momentum is conserved.']],['impact','Spread a stop over time',['A moving object begins the stopping interval.','A force reduces its momentum.','Velocity falls during the interval.','For the same change, longer time means smaller average force.']]];
export const frc1Films=Object.fromEntries(entries.map(([k,title,steps])=>['frc1-'+k,{title,steps,duration:16,render:p=>forceFigure({kind:k,movie:true,progress:p}),note:'Original illustrative worked example. Arrow lengths and trajectories are separately scaled; selected snapshots do not solve an entire force system unless explicitly stated. Time resets at replay. Surface, resistance, friction, material and bodily response are simplified. Generated graphs/data do not demonstrate physical measurements or unrestricted drawing. See Discover for the exact relationship, units and qualification/tier. No real stopping-distance or safety certification is inferred.'}]));
